<template><div><div class="page-head"><h2>消息中心</h2><el-tag type="success">站内信通道正常</el-tag></div><el-row :gutter="20"><el-col :span="15"><el-card shadow="never"><template #header>发布通知</template><el-form label-position="top"><el-form-item label="接收范围"><el-radio-group v-model="form.scope"><el-radio value="all">全站用户</el-radio><el-radio value="user">指定用户</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.scope==='user'" label="用户 ID"><el-input-number v-model="form.userId" :min="1"/></el-form-item><el-form-item label="通知标题"><el-input v-model="form.title" maxlength="100" show-word-limit/></el-form-item><el-form-item label="通知内容"><el-input v-model="form.content" type="textarea" :rows="7" maxlength="1000" show-word-limit/></el-form-item><el-button type="primary" :loading="sending" @click="send">立即发布</el-button></el-form></el-card></el-col><el-col :span="9"><el-card shadow="never"><template #header>发布说明</template><el-alert title="全站通知会为每位有效用户创建一条站内信。" type="info" :closable="false"/><ul><li>系统维护与版本更新</li><li>课程活动与学习提醒</li><li>重要规则和安全公告</li></ul></el-card></el-col></el-row></div></template>
<script setup>import{reactive,ref}from'vue';import{adminApi}from'@/api/admin';import{ElMessage,ElMessageBox}from'element-plus';const sending=ref(false),form=reactive({scope:'all',userId:null,title:'',content:''});async function send(){if(!form.title.trim()||!form.content.trim())return ElMessage.warning('请填写标题和内容');await ElMessageBox.confirm(`确定向${form.scope==='all'?'全站用户':'用户 '+form.userId}发布吗？`,'确认发布',{type:'warning'});sending.value=true;try{const r=await adminApi.sendNotification(form);ElMessage.success(`发布成功，共发送 ${r.data} 条`);form.title='';form.content=''}finally{sending.value=false}}</script>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page-head h2{margin:0}li{color:#606266;line-height:2}</style>
